# Paper figure app-fig:moe_seeds: Expert utilization of the LoL models in the mixture-of-experts comparison.
# Paper figure fig:moe: LoL is competitive with mixture of experts models.

### TRAIN ###
# Vanilla MoE baseline (seed 42).
.venv/bin/torchrun --standalone --nproc_per_node=8 train.py arch=vanilla_neo shape=360m seed=42 model.window=128 model.window_stride=64 model.moe_ffn=true model.moe_ffn_n_experts=3 model.moe_ffn_hidden_dim=1408 model.attention_strategy=shifted_window model.n_layer=24 training.max_steps=7269 training.batch_size=26 training.grad_accum_steps=5 training.flop_budget.enabled=true training.flop_budget.total_flops=1.7299736569617484e+19 training.max_lr=0.005 training.min_lr=0.0005 +training.router_max_lr=5e-05 +training.router_min_lr=5e-06 wandb_run_name=moe_seed42 data.data_dir=data/fineweb-30b
