.venv/bin/torchrun --standalone --nproc_per_node=8 train.py arch=lol_dynamic_window shape=360m seed=42 model.moe_ffn=true model.moe_ffn_scope=prelude_coda model.moe_ffn_n_experts=3 model.moe_ffn_hidden_dim=1408 model.recurrent_input_injection=diagonal model.n_experts=24 model.first_window_routing=learned_token_depth model.recurrent_depth=16 model.n_prelude_layers=4 model.n_coda_layers=4 model.depth_expert_film=true model.weight_tie_router=false training.max_steps=9393 training.batch_size=26 training.grad_accum_steps=5 training.flop_budget.enabled=true training.flop_budget.total_flops=1.7299736569617484e+19 training.max_lr=0.002 training.min_lr=0.0002 training.recurrence_curriculum.enabled=true training.recurrence_curriculum.mode=linear training.recurrence_curriculum.mean_schedule=one_minus_sqrt training.recurrence_curriculum.start_depth=1 training.recurrence_curriculum.target_mean=16 training.recurrence_curriculum.growth_steps=7044 +training.router_max_lr=5e-05 +training.router_min_lr=5e-06 wandb_run_name=lol_moe_seed42 data.data_dir=data/fineweb-30b
